import {
  SettingScope,
  isLoadableSettingScope,
  type LoadableSettingScope,
  type LoadedSettings,
} from '../config/settings.js';
import type { ModifiedScope } from './skillSettings.js';

export type FeatureToggleStatus = 'success' | 'no-op' | 'error';

/**
 * Metadata representing the result of a feature toggle operation.
 */
export interface FeatureToggleResult {
  status: FeatureToggleStatus;
  featureName: string;
  action: 'enable' | 'disable';
  /** Scopes where the feature's state was actually changed. */
  modifiedScopes: ModifiedScope[];
  /** Scopes where the feature was already in the desired state. */
  alreadyInStateScopes: ModifiedScope[];
  /** Error message if status is 'error'. */
  error?: string;
}

/**
 * Encapsulates the feature-specific logic required to toggle a feature on or
 * off within a given settings scope.
 *
 * Implementations describe how a particular feature (skills, agents, hooks,
 * etc.) is represented in settings, while the shared {@link enableFeature} and
 * {@link disableFeature} utilities handle scope iteration, result building, and
 * error handling.
 */
export interface FeatureToggleStrategy {
  /**
   * Returns `true` if the feature is not yet enabled in the given scope and
   * therefore needs to be enabled.
   */
  needsEnabling(
    settings: LoadedSettings,
    scope: LoadableSettingScope,
    featureName: string,
  ): boolean;
  /** Persists the change required to enable the feature in the given scope. */
  enable(
    settings: LoadedSettings,
    scope: LoadableSettingScope,
    featureName: string,
  ): void;
  /**
   * Returns `true` if the feature is explicitly disabled in the given scope.
   */
  isExplicitlyDisabled(
    settings: LoadedSettings,
    scope: LoadableSettingScope,
    featureName: string,
  ): boolean;
  /** Persists the change required to disable the feature in the given scope. */
  disable(
    settings: LoadedSettings,
    scope: LoadableSettingScope,
    featureName: string,
  ): void;
}

/**
 * Enables a feature across all writable scopes (User and Workspace) using the
 * provided {@link FeatureToggleStrategy}.
 */
export function enableFeature(
  settings: LoadedSettings,
  featureName: string,
  strategy: FeatureToggleStrategy,
): FeatureToggleResult {
  const writableScopes = [SettingScope.Workspace, SettingScope.User];
  const modifiedScopes: ModifiedScope[] = [];
  const alreadyInStateScopes: ModifiedScope[] = [];

  for (const scope of writableScopes) {
    if (!isLoadableSettingScope(scope)) {
      continue;
    }
    const scopePath = settings.forScope(scope).path;
    if (strategy.needsEnabling(settings, scope, featureName)) {
      strategy.enable(settings, scope, featureName);
      modifiedScopes.push({ scope, path: scopePath });
    } else {
      alreadyInStateScopes.push({ scope, path: scopePath });
    }
  }

  return {
    status: modifiedScopes.length === 0 ? 'no-op' : 'success',
    featureName,
    action: 'enable',
    modifiedScopes,
    alreadyInStateScopes,
  };
}

/**
 * Disables a feature in the specified scope using the provided
 * {@link FeatureToggleStrategy}.
 */
export function disableFeature(
  settings: LoadedSettings,
  featureName: string,
  scope: LoadableSettingScope,
  strategy: FeatureToggleStrategy,
): FeatureToggleResult {
  if ((scope as SettingScope) === SettingScope.Session) {
    return {
      status: 'error',
      featureName,
      action: 'disable',
      modifiedScopes: [],
      alreadyInStateScopes: [],
      error: 'Invalid settings scope',
    };
  }

  const scopePath = settings.forScope(scope).path;

  if (strategy.isExplicitlyDisabled(settings, scope, featureName)) {
    return {
      status: 'no-op',
      featureName,
      action: 'disable',
      modifiedScopes: [],
      alreadyInStateScopes: [{ scope, path: scopePath }],
    };
  }

  strategy.disable(settings, scope, featureName);

  return {
    status: 'success',
    featureName,
    action: 'disable',
    modifiedScopes: [{ scope, path: scopePath }],
    alreadyInStateScopes: [],
  };
}
